import heapq

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    def heuristic(node):
        # Simple heuristic: Euclidean distance between two points
        # In a grid-like graph, this could be Manhattan distance
        # For this implementation, we can use the node's coordinates as
        # an approximation of the distance to the goal.
        x1, y1 = start
        x2, y2 = node
        return abs(x1 - x2) + abs(y1 - y2)

    def reconstruct_path(came_from, current):
        total_path = [current]
        while current in came_from:
            current = came_from[current]
            total_path.append(current)
        return total_path[::-1]

    # Initialize the open and closed sets
    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {node: float('infinity') for node in graph}
    g_score[start] = 0
    f_score = {node: float('infinity') for node in graph}
    f_score[start] = heuristic(start)

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == goal:
            return reconstruct_path(came_from, current)

        for neighbor, _ in graph[current]:
            tentative_g_score = g_score[current] + 1  # Assuming all edges have the same cost

            if tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic(neighbor)
                if neighbor not in [node[1] for node in open_set]:
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return None

